import { test, expect } from '@playwright/test';

test.describe('Prefers Reduced Motion Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the application
    await page.goto('/');
  });

  test('should respect prefers-reduced-motion: reduce setting', async ({ page, context }) => {
    // Create a new context with prefers-reduced-motion set to reduce
    const reducedMotionContext = await context.browser()?.newContext({
      reducedMotion: 'reduce',
    });

    if (!reducedMotionContext) {
      throw new Error('Failed to create context with reduced motion');
    }

    const reducedMotionPage = await reducedMotionContext.newPage();
    await reducedMotionPage.goto('/');

    // Check that animations are disabled via CSS media query
    const animationDuration = await reducedMotionPage.evaluate(() => {
      const element = document.querySelector('[data-animated]');
      if (!element) return null;
      return window.getComputedStyle(element).animationDuration;
    });

    // Animation duration should be 0s or element should not have animation
    expect(animationDuration).toMatch(/^0s$/);

    // Verify that transitions are also disabled
    const transitionDuration = await reducedMotionPage.evaluate(() => {
      const element = document.querySelector('[data-transition]');
      if (!element) return null;
      return window.getComputedStyle(element).transitionDuration;
    });

    expect(transitionDuration).toMatch(/^0s$/);

    // Check that the prefers-reduced-motion media query is respected
    const mediaQueryMatches = await reducedMotionPage.evaluate(() => {
      return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    });

    expect(mediaQueryMatches).toBe(true);

    await reducedMotionPage.close();
    await reducedMotionContext.close();
  });

  test('should allow animations when prefers-reduced-motion is not set', async ({ page, context }) => {
    // Create a new context without reduced motion preference
    const normalContext = await context.browser()?.newContext({
      reducedMotion: 'no-preference',
    });

    if (!normalContext) {
      throw new Error('Failed to create context without reduced motion');
    }

    const normalPage = await normalContext.newPage();
    await normalPage.goto('/');

    // Check that animations are enabled
    const animationDuration = await normalPage.evaluate(() => {
      const element = document.querySelector('[data-animated]');
      if (!element) return null;
      const duration = window.getComputedStyle(element).animationDuration;
      return duration;
    });

    // Animation duration should not be 0s
    if (animationDuration) {
      expect(animationDuration).not.toMatch(/^0s$/);
    }

    // Verify that the prefers-reduced-motion media query does not match
    const mediaQueryMatches = await normalPage.evaluate(() => {
      return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    });

    expect(mediaQueryMatches).toBe(false);

    await normalPage.close();
    await normalContext.close();
  });

  test('should apply reduced motion styles to interactive elements', async ({ page, context }) => {
    const reducedMotionContext = await context.browser()?.newContext({
      reducedMotion: 'reduce',
    });

    if (!reducedMotionContext) {
      throw new Error('Failed to create context with reduced motion');
    }

    const reducedMotionPage = await reducedMotionContext.newPage();
    await reducedMotionPage.goto('/');

    // Find a button and verify it respects reduced motion
    const button = reducedMotionPage.getByRole('button').first();
    await expect(button).toBeVisible();

    // Check that button hover/focus animations are disabled
    const buttonAnimationDuration = await reducedMotionPage.evaluate(() => {
      const btn = document.querySelector('button');
      if (!btn) return null;
      return window.getComputedStyle(btn).animationDuration;
    });

    expect(buttonAnimationDuration).toMatch(/^0s$/);

    // Verify that the button is still interactive
    await button.click();
    await expect(button).toBeFocused();

    await reducedMotionPage.close();
    await reducedMotionContext.close();
  });

  test('should respect prefers-reduced-motion for scroll behavior', async ({ page, context }) => {
    const reducedMotionContext = await context.browser()?.newContext({
      reducedMotion: 'reduce',
    });

    if (!reducedMotionContext) {
      throw new Error('Failed to create context with reduced motion');
    }

    const reducedMotionPage = await reducedMotionContext.newPage();
    await reducedMotionPage.goto('/');

    // Check that scroll-behavior is set to auto (instant) instead of smooth
    const scrollBehavior = await reducedMotionPage.evaluate(() => {
      return window.getComputedStyle(document.documentElement).scrollBehavior;
    });

    expect(scrollBehavior).toBe('auto');

    await reducedMotionPage.close();
    await reducedMotionContext.close();
  });

  test('should maintain functionality while respecting reduced motion', async ({ page, context }) => {
    const reducedMotionContext = await context.browser()?.newContext({
      reducedMotion: 'reduce',
    });

    if (!reducedMotionContext) {
      throw new Error('Failed to create context with reduced motion');
    }

    const reducedMotionPage = await reducedMotionContext.newPage();
    await reducedMotionPage.goto('/');

    // Test that a modal or dropdown still functions without animations
    const triggerButton = reducedMotionPage.getByRole('button', { name: /open/i }).first();

    if (await triggerButton.isVisible()) {
      await triggerButton.click();

      // Verify the modal/dropdown appears (even without animation)
      const modal = reducedMotionPage.getByRole('dialog').first();
      await expect(modal).toBeVisible();

      // Verify we can interact with elements inside
      const closeButton = reducedMotionPage.getByRole('button', { name: /close/i }).first();
      if (await closeButton.isVisible()) {
        await closeButton.click();
        await expect(modal).not.toBeVisible();
      }
    }

    await reducedMotionPage.close();
    await reducedMotionContext.close();
  });
});
